import {useState, type ComponentProps} from 'react'
import {SelectPanel, Label, Button, Tooltip} from '@primer/react'
import {TasklistIcon, OrganizationIcon, TriangleDownIcon, CircleSlashIcon} from '@primer/octicons-react'

import type {SelectPanelItemInput as ItemInput} from '@primer/react'
import OrganizationSelectionTypeConfirmationDialog from './OrganizationSelectionTypeConfirmationDialog'
import styles from './OrganizationSelectionTypePanel.module.css'

interface OrganizationSelectionTypePanelProps {
  selectionType: string
  selectedOrganizationCount: number
  allOrgsCount: number
  canSelectAllOrganizations: boolean
  preventEditOrgSelectionTypeReason: string | null
  enterpriseTeamsOrgAssignmentLimit: number
  onSelectionChange: (selectionType: string) => void
}

export function OrganizationSelectionTypePanel({
  selectionType,
  selectedOrganizationCount,
  allOrgsCount,
  canSelectAllOrganizations,
  preventEditOrgSelectionTypeReason,
  enterpriseTeamsOrgAssignmentLimit,
  onSelectionChange,
}: OrganizationSelectionTypePanelProps) {
  const [isSelectPanelOpen, setIsSelectPanelOpen] = useState(false)
  const [filter, setFilter] = useState('')
  const [isConfirmationDialogOpen, setIsConfirmationDialogOpen] = useState(false)
  const [pendingSelectionType, setPendingSelectionType] = useState<string | null>(null)

  const allOrganizationsCountBelowLimit = allOrgsCount <= enterpriseTeamsOrgAssignmentLimit
  const items: ItemInput[] = [
    {
      leadingVisual: () => <TasklistIcon />,
      text: 'Specific organizations',
      description: `Select at least one organization. Max ${enterpriseTeamsOrgAssignmentLimit} organizations.`,
      descriptionVariant: 'block',
      id: 'selected',
    },
    {
      leadingVisual: () => <OrganizationIcon />,
      className: canSelectAllOrganizations ? styles.selectPanelWarnDescription : '',
      text: 'All organizations',
      description: !canSelectAllOrganizations
        ? 'This selection type is not yet supported.'
        : (!allOrganizationsCountBelowLimit &&
            `Option unavailable - a maximum of ${enterpriseTeamsOrgAssignmentLimit} organizations can be selected, but this enterprise has ${allOrgsCount}.`) ||
          'This applies to all current and future organizations.',
      descriptionVariant: 'block',
      id: 'all',
      disabled: !canSelectAllOrganizations || !allOrganizationsCountBelowLimit,
    },
    {
      leadingVisual: () => <CircleSlashIcon />,
      text: 'None',
      description: 'Your team will not have any organizations access.',
      descriptionVariant: 'block',
      id: 'disabled',
    },
  ]

  const filteredItems = items.filter(
    item => item.id === selectionType || item.text?.toLowerCase().startsWith(filter.toLowerCase()),
  )

  const renderAnchor = (anchorProps: ComponentProps<typeof Button>) => {
    const button = (
      <Button
        {...anchorProps}
        trailingAction={TriangleDownIcon}
        aria-haspopup="dialog"
        inactive={!!preventEditOrgSelectionTypeReason}
        data-testid="select-org-type-button"
      >
        {selectionType === 'all' ? (
          <span>
            <OrganizationIcon className="mr-2" />
            All organizations
            <Label variant="default" className="ml-2 mr-1">
              {selectedOrganizationCount}
            </Label>
          </span>
        ) : selectionType === 'selected' ? (
          <span>
            <TasklistIcon className="mr-2" />
            Specific organizations
            <Label variant="default" className="ml-2 mr-1">
              {selectedOrganizationCount}
            </Label>
          </span>
        ) : (
          <span className="mr-1">None</span>
        )}
      </Button>
    )

    return preventEditOrgSelectionTypeReason ? (
      <Tooltip text={preventEditOrgSelectionTypeReason} direction="n">
        {button}
      </Tooltip>
    ) : (
      button
    )
  }

  const handleConfirmSelectionChange = () => {
    if (pendingSelectionType) {
      onSelectionChange(pendingSelectionType)
      setPendingSelectionType(null)
    }
    setIsConfirmationDialogOpen(false)
  }

  const handleCancelSelectionChange = () => {
    setPendingSelectionType(null)
    setIsConfirmationDialogOpen(false)
  }

  return (
    <>
      {/* eslint-disable-next-line primer-react/no-system-props */}
      <SelectPanel
        overlayProps={{className: styles.selectPanelNoFilter}}
        renderAnchor={renderAnchor}
        title="Select organization type"
        items={filteredItems}
        showItemDividers
        open={isSelectPanelOpen}
        onOpenChange={setIsSelectPanelOpen}
        selected={items.find(item => item.id === selectionType)}
        onSelectedChange={(newSelected: ItemInput | undefined) => {
          if (newSelected && newSelected.id && newSelected.id !== selectionType) {
            setPendingSelectionType(`${newSelected.id}`)
            setIsSelectPanelOpen(false)
            setIsConfirmationDialogOpen(true)
          }
        }}
        onFilterChange={setFilter}
        width="medium"
        onCancel={() => setIsSelectPanelOpen(false)}
      />

      <OrganizationSelectionTypeConfirmationDialog
        isOpen={isConfirmationDialogOpen}
        onClose={handleCancelSelectionChange}
        onConfirm={handleConfirmSelectionChange}
        currentSelectionType={selectionType}
        newSelectionType={pendingSelectionType || ''}
      />
    </>
  )
}
