import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useEffect, useRef, useState} from 'react'
import {
  Heading,
  TextInput,
  FormControl,
  Pagination,
  Button,
  ConfirmationDialog,
  Checkbox,
  Banner,
  Link,
} from '@primer/react'
import {clsx} from 'clsx'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {updateSearchParams} from '@github-ui/history'
import {Blankslate} from '@primer/react/experimental'
import {useDebounce} from '@github-ui/use-debounce'

type Organization = {
  id: number
  name: string
  showRoute: string
}

type EnterpriseTeam = {
  id: number
  name: string
  slug: string
  showRoute: string
  organizationSelectionType: string
}

export interface StafftoolsBusinessTeamOrganizationsPayload {
  totalEntries: number
  totalPages: number
  enterpriseTeam: EnterpriseTeam
  orgs: Organization[]
  businessSlug: string
  killswitchEnabled: boolean
}

export function StafftoolsBusinessTeamOrganizationsView() {
  const useSynchronousCheckboxRef = useRef<HTMLInputElement | null>(null)
  const payload = useRoutePayload<StafftoolsBusinessTeamOrganizationsPayload>()
  const [urlSearchParams, setUrlSearchParams] = useState(() => new URLSearchParams(''))
  const [currentPage, setCurrentPage] = useState(1)
  const [searchboxValue, setSearchboxValue] = useState('')
  const [organizations, setOrganizations] = useState(payload.orgs)
  const [totalPages, setTotalPages] = useState(payload.totalPages)
  const [organizationToDestroy, setOrganizationToDestroy] = useState<Organization | null>(null)
  const [showConvertSelectionTypeDialog, setShowConvertSelectionTypeDialog] = useState(false)

  useEffect(() => {
    const params = new URLSearchParams(location.search)
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setUrlSearchParams(params)
    setSearchboxValue(params.get('query') || '')
    setCurrentPage(parseInt(params.get('page') || '1'))
  }, [setUrlSearchParams, setSearchboxValue, setCurrentPage])

  const setSearchParam = (key: string, value: string) => {
    urlSearchParams.set(key, value)
    updateSearchParams(urlSearchParams)
  }

  const onPageChange: Parameters<typeof Pagination>['0']['onPageChange'] = (e, page) => {
    e.preventDefault()
    paginate(page)
  }

  const destroyAssignment = async (org: Organization) => {
    await verifiedFetchJSON(
      `/stafftools/enterprises/${payload.businessSlug}/enterprise_teams/${
        payload.enterpriseTeam.id
      }/organizations/${org.id.toString()}?synchronous=${useSynchronousCheckboxRef.current?.checked ?? false}`,
      {
        method: 'DELETE',
        headers: {'Content-Type': 'application/json'},
      },
    )
    paginate(currentPage)
  }

  const setOrganizationSelectionType = async (newSelectionType: string) => {
    await verifiedFetchJSON(
      `/stafftools/enterprises/${payload.businessSlug}/enterprise_teams/${payload.enterpriseTeam.id}/organizations`,
      {
        method: 'PATCH',
        headers: {'Content-Type': 'application/json'},
        body: {organizationSelectionType: newSelectionType},
      },
    )
    location.reload()
  }

  const paginate = async (page: number): Promise<void> => {
    setSearchParam('page', page.toString())
    setCurrentPage(page)

    const result = await verifiedFetchJSON(
      `/stafftools/enterprises/${payload.businessSlug}/enterprise_teams/${
        payload.enterpriseTeam.id
      }/organizations?${urlSearchParams.toString()}`,
      {
        method: 'GET',
        headers: {Accept: 'application/json'},
      },
    )
    const data = await result.json()

    if (data && data.orgs) {
      setOrganizations(data.orgs)
      setTotalPages(data.totalPages)
    } else {
      setOrganizations([])
      setTotalPages(0)
    }
  }

  const handleSearchChange = (value: string) => {
    setSearchboxValue(value)
    debouncedSearch(value)
  }

  const debouncedSearch = useDebounce((searchValue: string) => {
    setSearchParam('query', searchValue)
    paginate(1)
  }, 300)

  return (
    <>
      <header className="Subhead">
        <Heading as="h2" className="Subhead-heading">
          <Link
            href={payload.enterpriseTeam.showRoute}
            data-testid={`team-link-${payload.enterpriseTeam.id}`}
            className={clsx('text-underline', 'tmp-mr-1')}
          >
            {payload.enterpriseTeam.name}
          </Link>
          / Organizations ({payload.totalEntries})
        </Heading>
      </header>
      {payload.totalEntries > 0 ? (
        <>
          {payload.enterpriseTeam.organizationSelectionType === 'all' && (
            <>
              <b>{payload.enterpriseTeam.name}</b> is assigned to all organizations in the enterprise.
              <Button variant="danger" size="small" onClick={() => setShowConvertSelectionTypeDialog(true)}>
                Destroy all org associations
              </Button>
              {showConvertSelectionTypeDialog && (
                <ConfirmationDialog
                  onClose={gesture => {
                    if (gesture === 'confirm') {
                      setOrganizationSelectionType('disabled')
                    }
                    setShowConvertSelectionTypeDialog(false)
                  }}
                  title="Convert organization selection type"
                  confirmButtonContent="Convert"
                  confirmButtonType="danger"
                >
                  {payload.killswitchEnabled && (
                    <>
                      <Banner
                        variant="warning"
                        hideTitle
                        title="Warning"
                        description={`The business team killswitch is currently enabled for ${payload.businessSlug}. Deleting this assignment may have unintended side effects.`}
                      />
                      <br />
                    </>
                  )}
                  <>
                    This will convert the <b>{payload.enterpriseTeam.name}</b> team&apos;s organization_selection_type
                    to &quot;disabled&quot; (None). The team will be unassigned from every organization.
                  </>
                </ConfirmationDialog>
              )}
              <br />
            </>
          )}
          <div className="d-flex tmp-mb-3">
            <FormControl>
              <FormControl.Label>Search organizations</FormControl.Label>
              <TextInput
                size="medium"
                placeholder="Find an organization..."
                value={searchboxValue}
                onChange={e => handleSearchChange(e.target.value)}
                data-testid={`search-input`}
              />
            </FormControl>
          </div>
          <div>
            <table
              className="site-admin-table"
              style={{border: `var(--borderColor-default)`, borderRadius: `var(--borderRadius-medium)`, width: '100%'}}
            >
              <thead>
                <tr>
                  <th style={{color: `var(--fgColor-default)`}}>Name</th>
                  {payload.enterpriseTeam.organizationSelectionType === 'selected' && (
                    <th style={{color: `var(--fgColor-default)`, textAlign: 'right'}}>Destroy</th>
                  )}
                </tr>
              </thead>
              <tbody>
                {organizations.length > 0 ? (
                  organizations.map((organization: Organization) => (
                    <tr key={organization.id}>
                      <td style={{width: '100%'}}>
                        <Link href={organization.showRoute} data-testid={`org-link-${organization.id}`}>
                          {organization.name}
                        </Link>
                      </td>
                      {payload.enterpriseTeam.organizationSelectionType === 'selected' && (
                        <td style={{textAlign: 'right'}}>
                          <Button onClick={() => setOrganizationToDestroy(organization)} variant="danger" size="small">
                            Destroy
                          </Button>
                        </td>
                      )}
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={1}>
                      <div className="fgColor-default">
                        <Blankslate>
                          <Blankslate.Heading>We couldn&apos;t find any matching organizations</Blankslate.Heading>
                          <Blankslate.Description>
                            No organizations matched your search criteria. Adjust your search to view results.
                          </Blankslate.Description>
                        </Blankslate>
                      </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
            {organizationToDestroy && (
              <ConfirmationDialog
                onClose={gesture => {
                  if (gesture === 'confirm') {
                    destroyAssignment(organizationToDestroy)
                  }
                  setOrganizationToDestroy(null)
                }}
                title="Remove organization assignment"
                confirmButtonContent="Remove"
                confirmButtonType="danger"
              >
                {payload.killswitchEnabled && (
                  <>
                    <Banner
                      variant="warning"
                      hideTitle
                      title="Warning"
                      description={`The business team killswitch is currently enabled for ${payload.businessSlug}. Deleting this assignment may have unintended side effects.`}
                    />
                    <br />
                  </>
                )}
                <>
                  Team <b>{payload.enterpriseTeam.name}</b> will lose its association with organization{' '}
                  <b>{organizationToDestroy.name}</b>.
                  <br />
                  <br />
                  <FormControl>
                    <Checkbox ref={useSynchronousCheckboxRef} value="synchronous" />
                    <FormControl.Label>Remove synchronously (bypass job queue)</FormControl.Label>
                  </FormControl>
                </>
              </ConfirmationDialog>
            )}
          </div>
          {organizations.length > 0 && (
            <Pagination pageCount={totalPages} currentPage={currentPage} onPageChange={onPageChange} />
          )}
        </>
      ) : (
        <div className="fgColor-default">
          <Blankslate>
            <Blankslate.Heading>No organizations are assigned to this enterprise team.</Blankslate.Heading>
          </Blankslate>
        </div>
      )}
    </>
  )
}
